/// <reference path="../pb_data/types.d.ts" />

/**
 * Порядковая метка записи по часам сервера.
 *
 * Зачем отдельное поле, когда есть updated.
 *
 * Поле updated приходит с устройства и означает «когда автор это изменил» —
 * по нему решается, чья версия новее. Для этого оно и нужно: правка,
 * сделанная в самолёте без сети, должна победить более раннюю, даже если
 * доехала позже.
 *
 * Но по нему же строилась и очередь доставки: клиент спрашивал «дай всё,
 * что новее моей отметки». А отметка бралась из тех же чужих часов. Стоило
 * тренеру записать что-то со своих часов, идущих на минуту вперёд, — его
 * курсор уезжал в будущее, и отчёты клиента, помеченные его собственными
 * часами, под условие уже не подходили. Запись лежала на сервере и не
 * доезжала до тренера никогда.
 *
 * seq ставит сервер и только сервер. Часы у него одни на всех, поэтому
 * очередь доставки перестаёт зависеть от того, насколько у кого спешат
 * телефоны. Разрешение конфликтов при этом не меняется — им по-прежнему
 * занимается updated.
 */

const stamp = (e) => {
  e.record.set('seq', new Date().getTime())
  e.next()
}

onRecordCreate(stamp, 'records')
onRecordUpdate(stamp, 'records')
